insert into public.cluster_translations (cluster_id, locale, slug, title, description, seo_title, seo_description) values ('occasion-tlusty-czwartek', 'de', 'tlusty-czwartek', 'Tłusty Czwartek', 'Tłusty Czwartek ist für uns der süße Donnerstag vor der Fastenzeit — Pączki, Faworki, etwas Fett, viel Freude, möglichst wenig Chaos in der Küche. Dieser Hub ordnet Klassiker, Technik und Einkauf für Haushalte in Deutschland.

Wir kuratieren bewusst kleiner als eine Bäckerei-Show. Nicht jeder muss am selben Tag Hefe und Frittüre meistern. Manche kaufen Pączki im Polenladen und machen Faworki zu Hause; andere umgekehrt. Der Kulturartikel zu Tłusty Czwartek setzt den Rahmen; Rezepte und der Faworki-Technik-Guide liefern Handwerk.

Timing hilft: Teig ruhen, Fett auf Temperatur prüfen, Chargen klein halten, Zucker sofort nach dem Frittieren. Freezer nimmt fertige Faworki selten so gut auf wie frische — lieber am Tag genießen oder Teig vorbereiten. Sicherheit: heißes Fett respektieren, Kinderabstand, Thermometer wenn unsicher.

Einkauf: Mehl, Eier, Schmalz oder Öl, Puderzucker, Marmelade für Pączki. Polenladen für Spezialitäten und fertige Teile. Dieser Hub verbindet Anlass und Rezepte — feiern ohne Leistungsdruck, süß mit Plan. Zusätzlich lohnt einmal im Monat ein kurzer Freezer-Check: unbeschriftete Reste klären, ältere Portionen nach vorne, einen Tag aus dem Freezer planen. Dieser Rhythmus hält Ordnung besser als einmaliges Großaufräumen. In der Diaspora baut ruhige Wiederholung den Geschmack von Zuhause.', 'Tłusty Czwartek Rezepte | Alemniam', 'Pączki und mehr für den Fettsdonnerstag.') on conflict (cluster_id, locale) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.cluster_translations (cluster_id, locale, slug, title, description, seo_title, seo_description) values ('occasion-tlusty-czwartek', 'pl', 'tlusty-czwartek', 'Tłusty Czwartek', 'Tłusty Czwartek to dla nas słodki czwartek przed postem — pączki, faworki, trochę tłuszczu, dużo radości, jak najmniej chaosu w kuchni. Ten hub porządkuje klasyki, technikę i zakupy dla domów w Niemczech.

Kuratorujemy świadomie skromniej niż show cukierniczy. Nie każdy musi tego dnia ogarnąć drożdże i fryturę. Jedni kupują pączki w sklepie polskim i robią faworki w domu; inni odwrotnie. Artykuł o Tłustym Czwartku daje ramę; przepisy i przewodnik techniki faworków dają rzemiosło.

Timing pomaga: ciasto odpocząć, tłuszcz sprawdzić, partie małe, cukier zaraz po smażeniu. Freezer rzadko bierze faworki tak dobrze jak świeże — lepiej cieszyć się tego dnia albo przygotować ciasto wcześniej. Bezpieczeństwo: szanować gorący tłuszcz, dystans dla dzieci, termometr gdy niepewnie.

Zakupy: mąka, jajka, smalec lub olej, cukier puder, dżem do pączków. Sklep polski na specjalności i gotowe części. Hub łączy okazję i przepisy — świętować bez presji wyniku, słodko z planem. Dodatkowo warto raz w miesiącu przejrzeć zamrażarkę: wyrzucić nieopisane resztki, przesunąć starsze porcje do przodu i zaplanować jeden dzień z Freezer. Taki rytuał utrzymuje porządek lepiej niż jednorazowe wielkie sprzątanie. W diasporze spokojna powtarzalność buduje smak domu.', 'Przepisy na Tłusty Czwartek | Alemniam', 'Pączki i więcej na Tłusty Czwartek.') on conflict (cluster_id, locale) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
